591	      </svg>
592	    </button>
593	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
594	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
595	    <div class="controls" role="group" aria-label="Circle controls">
596	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
597	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
598	    </div>
599	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset • <kbd>?</kbd> for help</div>
600	  </main>
601	
602	  <script defer>
603	    (() => {
604	      const COLORS = [
605	        { class: 'default', name: 'Default White' },
606	        { class: 'color-mode-1', name: 'Pink' },
607	        { class: 'color-mode-2', name: 'Teal' },
608	        { class: 'color-mode-3', name: 'Mint' },
609	        { class: 'color-mode-4', name: 'Purple' },
610	        { class: 'color-mode-5', name: 'Orange' }
611	      ];
612	
613	      const CONFIG = {
614	        storageKey: 'circle-state',
615	        tapDelay: 300,
616	        colorShiftDuration: 500,
617	        saveDebounceDuration: 100,
618	        keyDebounce: 50,
619	        isTouch: (() => {
620	          const hasCoarsePointer = window.matchMedia?.('(pointer:coarse)').matches ?? false;
621	          const hasTouchEvents = 'ontouchstart' in window;
622	          const hasMaxTouchPoints = (navigator.maxTouchPoints ?? 0) > 0;
623	          return hasCoarsePointer || hasTouchEvents || hasMaxTouchPoints;
624	        })()
625	      };
626	
627	      const el = {
628	        circle: document.getElementById('decorative-circle'),
629	        hint: document.getElementById('hint-text'),
630	        modeIndicator: document.getElementById('mode-indicator'),
631	        cycleBtn: document.getElementById('cycle-btn'),
632	        resetBtn: document.getElementById('reset-btn'),
633	        helpBtn: document.getElementById('help-btn'),
634	        helpModal: document.getElementById('help-modal'),
635	        modalClose: document.getElementById('modal-close')
636	      };
637	
638	      let state = { active: false, colorMode: 0 };
639	      let tapCount = 0;
640	      let tapTimeout = null;
641	      let animatingColorShift = false;
642	      let saveTimeout = null;
643	      let lastKeyTime = 0;
644	
645	      const haptic = (duration) => {
646	        try {
647	          navigator.vibrate?.(duration);
648	        } catch (e) {
649	          // Silently fail if vibration not available
650	        }
651	      };
652	
653	      const getColorClass = (mode) => COLORS[mode % COLORS.length]?.class || '';
654	      const getColorName = (mode) => COLORS[mode % COLORS.length]?.name || '';
655	
656	      const storage = {
657	        save() {
658	          clearTimeout(saveTimeout);
659	          saveTimeout = setTimeout(() => {
660	            try {
661	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
662	            } catch (e) {
663	              if (e?.name === 'QuotaExceededError') {
664	                console.warn('Storage quota exceeded');
665	              }
666	            }
667	          }, CONFIG.saveDebounceDuration);
668	        },
669	        load() {
670	          try {
671	            const saved = localStorage.getItem(CONFIG.storageKey);
672	            if (saved) {
673	              const parsed = JSON.parse(saved);
674	              if (parsed?.active !== undefined && parsed?.colorMode !== undefined) {
675	                state = parsed;
676	              }
677	            }
678	          } catch (e) {
679	            // Use default state on parse error
680	          }
681	        }
682	      };
683	
684	      const updateClasses = () => {
685	        if (!el.circle) return;
686	
687	        const colorClasses = COLORS.map(m => m.class);
688	        el.circle.classList.toggle('active', state.active);
689	        el.circle.setAttribute('aria-pressed', state.active.toString());
690	        el.circle.setAttribute('aria-expanded', (state.colorMode > 0).toString());
691	
692	        colorClasses.forEach(cls => {
693	          el.circle.classList.remove(cls);
694	        });
695	
696	        if (state.colorMode > 0) {
697	          el.circle.classList.add(getColorClass(state.colorMode));
698	        }
699	      };
700	
701	      const updateUI = () => {
702	        const hint = CONFIG.isTouch
703	          ? (state.active ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle')
704	          : (state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle');
705	        el.hint.textContent = hint;
706	
707	        const showMode = state.active && state.colorMode > 0;
708	        el.modeIndicator.classList.toggle('visible', showMode);
709	        if (showMode) {
710	          el.modeIndicator.textContent = `◆ ${getColorName(state.colorMode).toUpperCase()}`;
711	        }
712	      };
713	
714	      const applyState = () => {
715	        updateClasses();
716	        updateUI();
717	      };
718	
719	      const modal = {
720	        open: () => {
721	          if (!el.helpModal || !el.modalClose) return;
722	          el.helpModal.classList.add('active');
723	          el.modalClose.focus();
724	        },
725	        close: () => {
726	          if (!el.helpModal) return;
727	          el.helpModal.classList.remove('active');
728	          if (el.helpBtn) el.helpBtn.focus();
729	        }
730	      };
731	
732	      const toggleActive = () => {
733	        state.active = !state.active;
734	        haptic(10);
735	        applyState();
736	        storage.save();
737	      };
738	
739	      const cycleColor = () => {
740	        if (animatingColorShift || !el.circle) return;
741	
742	        animatingColorShift = true;
743	        state.colorMode = (state.colorMode + 1) % COLORS.length;
744	        state.active = true;
745	        haptic(20);
746	        el.circle.classList.add('color-shifting');
747	        setTimeout(() => {
748	          el.circle.classList.remove('color-shifting');
749	          animatingColorShift = false;
750	        }, CONFIG.colorShiftDuration);
751	        applyState();
752	        storage.save();
753	      };
754	
755	      const resetState = () => {
756	        state = { active: false, colorMode: 0 };
757	        haptic(10);
758	        applyState();
759	        storage.save();
760	      };
761	
762	      const handleTouchEnd = () => {
763	        tapCount++;
764	        haptic(10);
765	        clearTimeout(tapTimeout);
766	
767	        if (tapCount === 1) {
768	          tapTimeout = setTimeout(() => {
769	            if (tapCount === 1) {
770	              toggleActive();
771	            }
772	            tapCount = 0;
773	          }, CONFIG.tapDelay);
774	        } else if (tapCount >= 2) {
775	          tapCount = 0;
776	          cycleColor();
777	        }
778	      };
779	
780	      const keyHandlers = {
781	        ' ': toggleActive,
782	        'enter': toggleActive,
783	        'escape': resetState,
784	        'c': cycleColor,
785	        'r': resetState,
786	        '?': modal.open
787	      };
788	
789	      const handleKeyDown = (e) => {
790	        const key = e.key.toLowerCase();
791	        const handler = keyHandlers[key];
792	        if (!handler) return;
793	
794	        const now = Date.now();
795	        if (now - lastKeyTime < CONFIG.keyDebounce) return;
796	
797	        e.preventDefault();
798	        try {
799	          handler();
800	          lastKeyTime = now;
801	        } catch (err) {
802	          console.error('Keyboard handler error:', err);
803	        }
804	      };
805	
806	      const handleModalKeyDown = (e) => {
807	        if (e.key === 'Escape') {
808	          e.preventDefault();
809	          modal.close();
810	        }
811	      };
812	
813	      const handleModalBackdropClick = (e) => {
814	        if (e.target === el.helpModal) {
815	          modal.close();
816	        }
817	      };
818	
819	      const initListeners = () => {
820	        if (!el.circle) return;
821	
822	        el.circle.addEventListener('blur', () => {
823	          tapCount = 0;
824	          clearTimeout(tapTimeout);
825	        });
826	
827	        if (CONFIG.isTouch) {
828	          el.circle.addEventListener('touchend', handleTouchEnd, { passive: true });
829	          if (window.PointerEvent) {
830	            el.circle.addEventListener('pointerup', handleTouchEnd, { passive: true });
831	          }
832	        } else {
833	          el.circle.addEventListener('click', toggleActive, { passive: true });
834	          el.circle.addEventListener('dblclick', cycleColor, { passive: true });
835	        }
836	
837	        document.addEventListener('keydown', handleKeyDown);
838	
839	        el.cycleBtn?.addEventListener('click', cycleColor, { passive: true });
840	        el.resetBtn?.addEventListener('click', resetState, { passive: true });
841	        el.helpBtn?.addEventListener('click', modal.open, { passive: true });
842	        el.modalClose?.addEventListener('click', modal.close, { passive: true });
843	        el.helpModal?.addEventListener('click', handleModalBackdropClick, { passive: true });
844	        el.helpModal?.addEventListener('keydown', handleModalKeyDown);
845	      };
846	
847	      const initApp = () => {
848	        if (!el.circle) {
849	          console.error('Circle element not found');
850	          return;
851	        }
852	        storage.load();
853	        applyState();
854	        initListeners();
855	        el.circle.focus?.();
856	      };
857	
858	      const ensureSave = () => {
859	        clearTimeout(saveTimeout);
860	        try {
861	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
862	        } catch (e) {
863	          // Silently fail on storage errors during page hide
864	        }
865	      };
866	
867	      if (document.readyState === 'loading') {
868	        document.addEventListener('DOMContentLoaded', initApp);
869	      } else {
870	        initApp();
871	      }
872	
873	      window.addEventListener('pagehide', ensureSave);
874	    })();
875	  </script>
876	</body>
877	</html>
